<?php
require_once 'auth.php'; require_once 'db.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id){header('Location: manage_products.php');exit;}
$q=$conn->prepare("SELECT * FROM products WHERE id=?");$q->execute([$id]);$p=$q->fetch();if(!$p){header('Location: manage_products.php');exit;}
$price=(float)$p['price'];$discount=(float)$p['discount'];$final=$price*(1-$discount/100);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>View Product</title><script src="https://cdn.tailwindcss.com"></script></head><body class="bg-gray-100 min-h-screen"><header class="bg-gray-950 text-white p-5 flex justify-between"><h1 class="font-bold text-xl">Product Details</h1><a href="manage_products.php" class="bg-gray-700 px-4 py-2 rounded">Back</a></header><main class="max-w-4xl mx-auto p-6"><div class="bg-white rounded-2xl shadow p-8 grid md:grid-cols-2 gap-8"><div class="bg-gray-50 rounded-xl flex items-center justify-center min-h-72"><img src="src/<?= htmlspecialchars(basename($p['product_image']??''),ENT_QUOTES,'UTF-8') ?>" class="max-h-80 max-w-full object-contain p-4" alt=""></div><div><p class="text-blue-600 font-bold uppercase"><?= htmlspecialchars($p['cat'],ENT_QUOTES,'UTF-8') ?></p><h2 class="text-3xl font-black mt-2"><?= htmlspecialchars($p['product_name'],ENT_QUOTES,'UTF-8') ?></h2><p class="text-3xl font-black mt-6">$<?= number_format($final,2) ?></p><?php if($discount>0): ?><p class="line-through text-gray-400">$<?= number_format($price,2) ?></p><?php endif; ?><p class="mt-4">Size: <?= htmlspecialchars($p['size']??'',ENT_QUOTES,'UTF-8') ?></p><p class="mt-2">Available quantity: <?= (int)$p['quantity'] ?></p><a href="edit_product.php?id=<?= (int)$p['id'] ?>" class="inline-block mt-6 bg-yellow-500 text-white px-5 py-3 rounded-lg font-bold">Update Product</a></div></div></main></body></html>
